// Transforma el texto de rutas entregado por OS nativo en el diccionario y compositeKey
const result = $input.first().json.stdout;
if (!result) return [];

const lines = result.split('\n').filter(l => l.trim() !== '');
const EXT = /\.(jpg|jpeg|png|webp|gif)$/i;

// Nomalización FUERTE: Quita acentos, todo a MAYÚSCULAS y elimina todo lo que no sea A-Z o números
function normalizeName(str) {
  if (!str) return '';
  return String(str)
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // Quitar acentos/diacríticos
    .toUpperCase() // Convertir a mayúsculas
    .replace(/[^A-Z0-9]/g, ''); // Eliminar espacios, guiones, símbolos de $, etc.
}

const out = [];

for (const fullPath of lines) {
  if (!EXT.test(fullPath)) continue;

  const parts = fullPath.split('/');
  const fileName = parts.pop();
  const categoryRaw = parts.pop();

  if (!categoryRaw) continue;

  const category = normalizeName(categoryRaw);
  const baseName = fileName.replace(/\.[^.]+$/i, ''); // remover extensión
  const matchKey = normalizeName(baseName);

  // Nuestra llave maestra inquebrantable
  const compositeKey = matchKey + '|' + category;

  out.push({ json: { path: fullPath, fileName, categoryRaw, category, matchKey, compositeKey } });
}

return out;

// Limpieza + categoría desde secciones (--- ACCESORIOS ---) y compositeKey para emparejar
const items = $input.all();
const cleaned = [];
const COL = { 
  codigo: 'CÓDIGO', 
  nombre: 'NOMBRE', 
  precioUsd: 'PRECIO USD', 
  precioCup: 'PRECIO CUP',
  precioAntiguoUsd: 'PRECIO ANTIGUO USD',
  precioAntiguoCup: 'PRECIO ANTIGUO CUP',
  estado: 'ESTADO' 
};

function safeNum(val) {
  if (val === null || val === undefined || val === '') return null;
  if (typeof val === 'number' && !Number.isNaN(val)) return val;
  const s = String(val).replace(/[^0-9.,]/g, '').replace(',', '.');
  const n = parseFloat(s);
  return Number.isNaN(n) ? null : n;
}

function safeStr(val) {
  if (val === null || val === undefined) return '';
  return String(val).trim();
}

function normalizeName(str) {
  if (!str) return '';
  return String(str)
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '');
}

function isSectionHeader(codigo, nombre) {
  const c = String(codigo || '').trim();
  const n = safeStr(nombre);
  return c.includes('---') || (!n && !c);
}

function sectionToCategory(codigo) {
  const m = String(codigo).match(/---\s*([^---]+)\s*---/);
  return m ? normalizeName(m[1]) : null;
}

let currentCategory = '';

for (const item of items) {
  const row = item.json || item;
  const codigoRaw = row[COL.codigo];
  const nombre = safeStr(row[COL.nombre]);

  if (isSectionHeader(codigoRaw, nombre)) {
    const cat = sectionToCategory(codigoRaw);
    if (cat) currentCategory = cat;
    continue;
  }

  if (!nombre) continue;

  const usd = safeNum(row[COL.precioUsd]);
  const cup = safeNum(row[COL.precioCup]);
  const oldUsd = safeNum(row[COL.precioAntiguoUsd]);
  const oldCup = safeNum(row[COL.precioAntiguoCup]);

  const matchKey = normalizeName(nombre);
  const compositeKey = matchKey + '|' + currentCategory;

  // Determinar si hay rebaja real (actual < antiguo)
  const isSale = (oldUsd !== null && usd < oldUsd);

  // Formateo de precios
  const usdFormatted = usd !== null ? `$${usd.toFixed(2)}` : 'N/A';
  const cupFormatted = cup !== null ? `${cup.toLocaleString()} CUP` : 'N/A';
  const oldUsdFormatted = oldUsd !== null ? `$${oldUsd.toFixed(2)}` : '';
  const oldCupFormatted = oldCup !== null ? `${oldCup.toLocaleString()} CUP` : '';

  // Cálculo de ahorro
  let savingsLabel = '';
  if (isSale) {
    const diff = oldUsd - usd;
    savingsLabel = `AHORRAS $${diff.toFixed(2)}`;
  }

  cleaned.push({ 
    json: { 
      productId: nombre,
      usd, 
      cup, 
      oldUsd,
      oldCup,
      usdFormatted, 
      cupFormatted,
      oldUsdFormatted,
      oldCupFormatted,
      isSale,
      savingsLabel,
      category: currentCategory,
      matchKey,
      compositeKey
    } 
  });
}

return cleaned;
